    books: ['esther'], story: [s('Esther 2', 'esther', 2, 'Chosen as queen.'), s('Esther 4', 'esther', 4, '"For such a time as this… if I perish, I perish."'), s('Esther 7', 'esther', 7, 'Exposes Haman.')],
